cases.good:
// 1. dot-split (standard: episode-1.en.srt)
const parts = filenameWithoutExt.split('.');
if (parts.length >= 2 && BCP47_PATTERN.test(parts.at(-1))) {
  const primary = parts.at(-1).split('-')[0].toLowerCase();
  if (isValidIsoCode(primary)) return primary;
}
// 2. kebab-split fallback (kisskh: episode-1-en.srt) — isValidIsoCode rejects 'memories','episode','1'
const kebabParts = filenameWithoutExt.split('-');
if (kebabParts.length >= 2 && BCP47_PATTERN.test(kebabParts.at(-1))) {
  const primary = kebabParts.at(-1).split('-')[0].toLowerCase();
  if (isValidIsoCode(primary)) return primary;
}
// 3. folder segment fallback → 'unknown'

cases.bad:
// kebab-split: ['eng','2'] → candidate = '2' → BCP47_PATTERN fails (needs 2-3 letters) → skip
// dot-split: ['eng-2'] → length 1 → skip
// folder segment: 'subtitles' → not BCP47 → skip
return 'unknown'; // eng-2.vtt, spa-5.vtt, por-4.vtt all missed

cases.good:
// lang-index pattern: match the WHOLE filename base, not just the last segment
const langIndexMatch = /^([a-z]{2,3})-\d+$/i.exec(filenameWithoutExt);
if (langIndexMatch) {
  const primary = langIndexMatch[1].toLowerCase();
  if (isValidIsoCode(primary)) return primary; // 'sub-2.vtt' → 'sub' rejected (not ISO)
}
